wp = get_waypoint()
gp = get_goal()
log("start")

waypoint_reached = False

for i in range(12):
    pose = get_pose()
    dist_way = distance_to(wp['x'], wp['y'])
    dist_goal = distance_to(gp['x'], gp['y'])

    if not waypoint_reached:
        if dist_way <= 0.6:
            waypoint_reached = True
            stop(1)
        else:
            target_h = heading_to(wp['x'], wp['y'])
            err = target_h - pose['heading_deg']
            if err > 180:
                err -= 360
            elif err < -180:
                err += 360
            wz = err * (0.8 / 180)
            if wz > 0.8:
                wz = 0.8
            if wz < -0.8:
                wz = -0.8
            walk(0.5, 0, wz, 5)
    else:
        if dist_goal <= 0.5:
            stop(1)
            log("goal reached")
            break
        target_h = heading_to(gp['x'], gp['y'])
        err = target_h - pose['heading_deg']
        if err > 180:
            err -= 360
        elif err < -180:
            err += 360
        wz = err * (0.8 / 180)
        if wz > 0.8:
            wz = 0.8
        if wz < -0.8:
            wz = -0.8
        walk(0.5, 0, wz, 5)

state = 0
for _ in range(60):
    pose = get_pose()
    x, y, h = pose['x'], pose['y'], pose['heading_deg']

    # check waypoint passage
    if state == 0:
        if distance_to(0.859, 1.71) <= 0.6:
            state = 1
            log("waypoint passed")

    # check goal reached
    if state == 1:
        if distance_to(3.027, 1.204) <= 0.5:
            stop(1)
            log("goal reached")
            break

    # select target based on current state
    if state == 0:
        tx, ty = 0.859, 1.71
    else:
        tx, ty = 3.027, 1.204

    # compute heading error and wheel turn rate
    des_h = heading_to(tx, ty)
    err = des_h - h
    err = (err + 180) % 360 - 180
    wz = err * 0.12
    if wz > 0.5:
        wz = 0.5
    if wz < -0.5:
        wz = -0.5

    # forward speed: slower near goal
    if state == 1 and distance_to(3.027, 1.204) < 0.8:
        vx = 0.2
    else:
        vx = 0.4
    vy = 0.0

    res = walk(vx, vy, wz, 1)
    if res.get('fell', False):
        log("fell")
        break
